/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

/* Builds a 0xB000-tagged 16-bit entry ID: group 0 uses index as is, group 1 adds 0x25, other groups add 0x4B. */ s32 makeMenuEntryId(s32 group, s32 index) {
    s32 groupId;
    s32 id;
    s32 offsetIndex;

    groupId = group & 0xFFFF;
    switch (groupId) {                              /* irregular */
    default:
        offsetIndex = index + 0x4B;
        goto block_6;
    case 0:
        id = index & 0xFFFF;
        break;
    case 1:
        offsetIndex = index + 0x25;
block_6:
        id = offsetIndex & 0xFFFF;
        break;
    }
    return id | 0xB000;
}
